/**
 * Normalizes anonymous variable tokens so structurally identical trees compare equal even if hashed suffixes differ.
 * Standalone identifiers only (left boundary must be a non-word char). Word chars = [A-Za-z0-9_].
 *
 * Families are prefixes (including trailing underscore), e.g. "_anon_path_". Pre-numbered tails (digits-only) are
 * preserved and reserve their numbers.
 */
public final class VarNameNormalizer {

	private static final List<String> DEFAULT_PREFIXES = Arrays.asList(
			"_describe_",
			"_anon_collection_",
			"_anon_path_inverse_",
			"_anon_path_",
			"_anon_having_",
			"_anon_"
	);

	private VarNameNormalizer() {
	}

	public static String normalizeVars(String input) {
		return normalizeVars(input, DEFAULT_PREFIXES);
	}

	/**
	 * Canonical model text for anonymous constant symbols and the existing generated-placeholder families. Roles come
	 * from the model, never from RDF text or a genuine variable's spelling. A bijection preserves repeated-name
	 * relationships across the unchanged scope tree; equal Values do not merge distinct symbols. The source is not
	 * modified, and no textual normalization is applied to Values.
	 */
	public static String normalizeModelVariables(QueryModelNode expression) {
		if (expression == null) {
			return null;
		}
		ModelSymbols symbols = new ModelSymbols();
		expression.visit(symbols);
		Map<String, String> names = symbols.canonicalNames();
		QueryModelNode[] copy = { expression.clone() };
		copy[0].visit(new AbstractQueryModelVisitor<RuntimeException>() {
			private String name(String original) {
				return names.getOrDefault(original, original);
			}

			private void replace(QueryModelNode original, QueryModelNode replacement) {
				if (original.getParentNode() == null) {
					copy[0] = replacement;
				} else {
					original.replaceWith(replacement);
				}
			}

			@Override
			public void meet(Var variable) {
				String renamed = name(variable.getName());
				if (!renamed.equals(variable.getName())) {
					Var replacement = Var.of(renamed, variable.getValue(), variable.isAnonymous(),
							variable.isConstant(), variable.isBNode());
					copyAnnotations(variable, replacement);
					replace(variable, replacement);
				}
			}

			@Override
			public void meet(ExtensionElem element) {
				element.setName(name(element.getName()));
				super.meet(element);
			}

			@Override
			public void meet(ProjectionElem element) {
				// Only the source follows a generated symbol; a projection target is a genuine output name.
				element.setName(name(element.getName()));
			}

			@Override
			public void meet(Group group) {
				List<String> renamed = new ArrayList<>(group.getGroupBindingNames().size());
				group.getGroupBindingNames().forEach(original -> renamed.add(name(original)));
				group.setGroupBindingNames(renamed);
				super.meet(group);
			}

			@Override
			public void meet(GroupElem element) {
				element.setName(name(element.getName()));
				super.meet(element);
			}

			@Override
			public void meet(ValueExprTripleRef triple) {
				super.meet(triple);
				String renamed = name(triple.getExtVarName());
				if (!Objects.equals(renamed, triple.getExtVarName())) {
					ValueExprTripleRef replacement = new ValueExprTripleRef(renamed, triple.getSubjectExpr(),
							triple.getPredicateExpr(), triple.getObjectExpr());
					copyAnnotations(triple, replacement);
					replace(triple, replacement);
				}
			}
		});
		return copy[0].toString();
	}

	private static void copyAnnotations(QueryModelNode source, QueryModelNode target) {
		if (source instanceof VariableScopeChange sourceScope && target instanceof VariableScopeChange targetScope) {
			targetScope.setVariableScopeChange(sourceScope.isVariableScopeChange());
		}
		target.setCostEstimate(source.getCostEstimate());
		target.setResultSizeEstimate(source.getResultSizeEstimate());
		target.setResultSizeActual(source.getResultSizeActual());
		target.setTotalTimeNanosActual(source.getTotalTimeNanosActual());
	}

	private enum AnonymousRole {
		CONSTANT,
		PLACEHOLDER,
		CONFLICT
	}

	private static final class ModelSymbols extends AbstractQueryModelVisitor<RuntimeException> {
		private final Map<String, AnonymousRole> anonymous = new LinkedHashMap<>();
		private final Set<String> genuine = new HashSet<>();
		private final Set<String> referenced = new HashSet<>();

		private void anonymous(String name, AnonymousRole role) {
			anonymous.merge(name, role, (first, second) -> first == second ? first : AnonymousRole.CONFLICT);
		}

		@Override
		public void meet(Var variable) {
			String name = variable.getName();
			if (variable.isAnonymous() && variable.hasValue()) {
				anonymous(name, AnonymousRole.CONSTANT);
			} else if (variable.isAnonymous() && !variable.hasValue() && placeholderFamily(name) != null) {
				anonymous(name, AnonymousRole.PLACEHOLDER);
			} else {
				genuine.add(name);
			}
		}

		@Override
		public void meet(ExtensionElem element) {
			String name = element.getName();
			if (element.isAnonymousTarget()) {
				if (element.getExpr() instanceof ValueConstant) {
					anonymous(name, AnonymousRole.CONSTANT);
				} else if (placeholderFamily(name) != null) {
					anonymous(name, AnonymousRole.PLACEHOLDER);
				}
			} else {
				genuine.add(name);
			}
			referenced.add(name);
			super.meet(element);
		}

		@Override
		public void meet(ProjectionElem element) {
			referenced.add(element.getName());
			element.getProjectionAlias().ifPresent(genuine::add);
		}

		@Override
		public void meet(Group group) {
			referenced.addAll(group.getGroupBindingNames());
			super.meet(group);
		}

		@Override
		public void meet(GroupElem element) {
			if (element.isAnonymousTarget() && placeholderFamily(element.getName()) != null) {
				anonymous(element.getName(), AnonymousRole.PLACEHOLDER);
			} else {
				genuine.add(element.getName());
			}
			super.meet(element);
		}

		@Override
		public void meet(BindingSetAssignment assignment) {
			genuine.addAll(assignment.getDeclaredBindingNames());
			if (assignment.hasRepeatableBindingSets() && assignment.getBindingSets() != null) {
				for (BindingSet row : assignment.getBindingSets()) {
					genuine.addAll(row.getBindingNames());
				}
			}
		}

		@Override
		public void meet(ValueExprTripleRef triple) {
			referenced.add(triple.getExtVarName());
			super.meet(triple);
		}

		private Map<String, String> canonicalNames() {
			for (String name : referenced) {
				if (!anonymous.containsKey(name)) {
					genuine.add(name);
				}
			}
			Set<String> occupied = new HashSet<>(genuine);
			for (var symbol : anonymous.entrySet()) {
				String family = placeholderFamily(symbol.getKey());
				if (symbol.getValue() == AnonymousRole.CONFLICT
						|| symbol.getValue() == AnonymousRole.PLACEHOLDER && family != null
								&& isAllDigits(symbol.getKey(), family.length(), symbol.getKey().length())) {
					occupied.add(symbol.getKey());
				}
			}
			Map<String, String> result = new HashMap<>();
			Map<String, Integer> counters = new HashMap<>();
			for (var symbol : anonymous.entrySet()) {
				String original = symbol.getKey();
				if (genuine.contains(original) || symbol.getValue() == AnonymousRole.CONFLICT) {
					continue;
				}
				String family = symbol.getValue() == AnonymousRole.CONSTANT ? "_const_"
						: placeholderFamily(original);
				if (symbol.getValue() == AnonymousRole.PLACEHOLDER
						&& isAllDigits(original, family.length(), original.length())) {
					continue;
				}
				int next = counters.getOrDefault(family, symbol.getValue() == AnonymousRole.CONSTANT ? 0 : 1);
				String candidate;
				do {
					candidate = family + next++;
				} while (!occupied.add(candidate));
				counters.put(family, next);
				result.put(original, candidate);
			}
			return result;
		}
	}

	private static String placeholderFamily(String name) {
		if (name == null) {
			return null;
		}
		for (String family : DEFAULT_PREFIXES) {
			if (name.startsWith(family) && name.length() > family.length()) {
				boolean word = true;
				for (int i = family.length(); word && i < name.length(); i++) {
					word = isWordChar(name.charAt(i));
				}
				if (word) {
					return family;
				}
			}
		}
		return null;
	}

	public static String normalizeVars(String input, List<String> families) {
		if (input == null || input.isEmpty()) {
			return input;
		}

		// Longest-first so more specific families win (e.g., path_inverse before path).
		List<String> fams = new ArrayList<>(families);
		fams.sort((a, b) -> Integer.compare(b.length(), a.length()));

		// Reserve numbers per family with BitSet for O(1) next-id.
		final Map<String, BitSet> reserved = new HashMap<>();
		for (String f : fams) {
			reserved.put(f, new BitSet());
		}

		// If there is a shared underscore-terminated prefix (e.g., "_anon_"), use the fast path.
		final String shared = sharedPrefixEndingWithUnderscore(fams);

		if (!shared.isEmpty()) {
			reservePreNumberedFast(input, fams, reserved, shared);
			return rewriteHashedFast(input, fams, reserved, shared);
		}

		// Generic path: bucket by first char; still no regionMatches.
		final Map<Character, List<String>> byFirst = bucketByFirstChar(fams);
		reservePreNumberedGeneric(input, byFirst, reserved);
		return rewriteHashedGeneric(input, byFirst, reserved);
	}

	/* ============================ Fast path (shared prefix) ============================ */

	private static void reservePreNumberedFast(String s, List<String> fams, Map<String, BitSet> reserved,
			String shared) {
		final int n = s.length();
		int i = s.indexOf(shared, 0);
		while (i >= 0) {
			if ((i == 0 || !isWordChar(s.charAt(i - 1)))) {
				String family = matchFamilyAt(s, i, fams);
				if (family != null) {
					final int tailStart = i + family.length();
					if (tailStart < n && isWordChar(s.charAt(tailStart))) {
						int j = tailStart + 1;
						while (j < n && isWordChar(s.charAt(j))) {
							j++;
						}
						int num = parsePositiveIntOrMinusOne(s, tailStart, j);
						if (num >= 0) {
							reserved.get(family).set(num);
						}
					}
				}
			}
			i = s.indexOf(shared, i + 1);
		}
	}

	private static String rewriteHashedFast(String s, List<String> fams, Map<String, BitSet> reserved, String shared) {
		final int n = s.length();
		final StringBuilder out = new StringBuilder(n + 16);
		final Map<String, String> mapping = new LinkedHashMap<>();

		int writePos = 0;
		int i = s.indexOf(shared, 0);
		while (i >= 0) {
			if (!(i == 0 || !isWordChar(s.charAt(i - 1)))) {
				i = s.indexOf(shared, i + 1);
				continue;
			}

			String family = matchFamilyAt(s, i, fams);
			if (family == null) {
				i = s.indexOf(shared, i + 1);
				continue;
			}

			final int tailStart = i + family.length();
			if (tailStart >= n || !isWordChar(s.charAt(tailStart))) {
				i = s.indexOf(shared, i + 1);
				continue;
			}

			int j = tailStart + 1;
			while (j < n && isWordChar(s.charAt(j))) {
				j++;
			}

			if (isAllDigits(s, tailStart, j)) {
				// keep as-is
				out.append(s, writePos, j);
				writePos = j;
			} else {
				String original = s.substring(i, j); // small, acceptable allocation
				String replacement = mapping.get(original);
				if (replacement == null) {
					BitSet bs = reserved.get(family);
					int next = bs.nextClearBit(1);
					bs.set(next);
					replacement = family + next;
					mapping.put(original, replacement);
				}
				out.append(s, writePos, i).append(replacement);
				writePos = j;
			}

			i = s.indexOf(shared, j);
		}
		out.append(s, writePos, n);
		return out.toString();
	}

	/**
	 * Find the specific family that matches at offset i. fams must be sorted longest-first. No regionMatches; inline
	 * char checks.
	 */
	private static String matchFamilyAt(String s, int i, List<String> fams) {
		final int n = s.length();
		for (String f : fams) {
			int len = f.length();
			if (i + len > n) {
				continue;
			}
			// manual "startsWithAt"
			boolean ok = true;
			for (int k = 0; k < len; k++) {
				if (s.charAt(i + k) != f.charAt(k)) {
					ok = false;
					break;
				}
			}
			if (ok) {
				return f;
			}
		}
		return null;
	}

	/* ============================ Generic path (no common prefix) ============================ */

	private static void reservePreNumberedGeneric(String s, Map<Character, List<String>> byFirst,
			Map<String, BitSet> reserved) {
		final int n = s.length();
		for (int i = 0; i < n;) {
			char c = s.charAt(i);
			if (!(i == 0 || !isWordChar(s.charAt(i - 1)))) {
				i++;
				continue;
			}
			List<String> cand = byFirst.get(c);
			if (cand == null) {
				i++;
				continue;
			}

			String family = matchFamilyAtFromBucket(s, i, cand);
			if (family == null) {
				i++;
				continue;
			}

			int tailStart = i + family.length();
			if (tailStart >= n || !isWordChar(s.charAt(tailStart))) {
				i++;
				continue;
			}

			int j = tailStart + 1;
			while (j < n && isWordChar(s.charAt(j))) {
				j++;
			}

			int num = parsePositiveIntOrMinusOne(s, tailStart, j);
			if (num >= 0) {
				reserved.get(family).set(num);
			}

			i = j; // jump past the token
		}
	}

	private static String rewriteHashedGeneric(String s, Map<Character, List<String>> byFirst,
			Map<String, BitSet> reserved) {
		final int n = s.length();
		final StringBuilder out = new StringBuilder(n + 16);
		final Map<String, String> mapping = new LinkedHashMap<>();

		int writePos = 0;
		for (int i = 0; i < n;) {
			char c = s.charAt(i);
			if (!(i == 0 || !isWordChar(s.charAt(i - 1)))) {
				i++;
				continue;
			}
			List<String> cand = byFirst.get(c);
			if (cand == null) {
				i++;
				continue;
			}

			String family = matchFamilyAtFromBucket(s, i, cand);
			if (family == null) {
				i++;
				continue;
			}

			int tailStart = i + family.length();
			if (tailStart >= n || !isWordChar(s.charAt(tailStart))) {
				i++;
				continue;
			}

			int j = tailStart + 1;
			while (j < n && isWordChar(s.charAt(j))) {
				j++;
			}

			if (isAllDigits(s, tailStart, j)) {
				// keep as-is
				out.append(s, writePos, j);
				writePos = j;
			} else {
				String original = s.substring(i, j); // small, acceptable allocation
				String replacement = mapping.get(original);
				if (replacement == null) {
					BitSet bs = reserved.get(family);
					int next = bs.nextClearBit(1);
					bs.set(next);
					replacement = family + next;
					mapping.put(original, replacement);
				}
				out.append(s, writePos, i).append(replacement);
				writePos = j;
			}

			i = j;
		}
		out.append(s, writePos, n);
		return out.toString();
	}

	private static Map<Character, List<String>> bucketByFirstChar(List<String> fams) {
		final Map<Character, List<String>> byFirst = new HashMap<>();
		for (String f : fams) {
			char c = f.charAt(0);
			byFirst.computeIfAbsent(c, k -> new ArrayList<>()).add(f);
		}
		return byFirst;
	}

	private static String matchFamilyAtFromBucket(String s, int i, List<String> fams) {
		final int n = s.length();
		for (String f : fams) {
			int len = f.length();
			if (i + len > n) {
				continue;
			}
			boolean ok = true;
			for (int k = 0; k < len; k++) {
				if (s.charAt(i + k) != f.charAt(k)) {
					ok = false;
					break;
				}
			}
			if (ok) {
				return f;
			}
		}
		return null;
	}

	/* =============================== Utilities =============================== */

	private static String sharedPrefixEndingWithUnderscore(List<String> fams) {
		if (fams.isEmpty()) {
			return "";
		}
		char[] acc = fams.get(0).toCharArray();
		int end = acc.length;
		for (int i = 1; i < fams.size(); i++) {
			String f = fams.get(i);
			end = Math.min(end, f.length());
			for (int k = 0; k < end; k++) {
				if (acc[k] != f.charAt(k)) {
					end = k;
					break;
				}
			}
		}
		while (end > 0 && acc[end - 1] != '_') {
			end--;
		}
		if (end == 0) {
			return "";
		}
		return new String(acc, 0, end);
	}

	private static boolean isAllDigits(String s, int start, int end) {
		for (int i = start; i < end; i++) {
			if (!Character.isDigit(s.charAt(i))) {
				return false;
			}
		}
		return true;
	}

	private static boolean isWordChar(char c) {
		return Character.isLetterOrDigit(c) || c == '_';
	}

	private static int parsePositiveIntOrMinusOne(String s, int start, int end) {
		int n = 0;
		for (int i = start; i < end; i++) {
			char c = s.charAt(i);
			if (!Character.isDigit(c)) {
				return -1;
			}
			n = (n * 10) + (c - '0');
		}
		return n;
	}
}
